import{detectPackageManager}from"#setup/package-manager.js";import{createPromptCommandOutput,withPhase}from"#setup/cli/index.js";import{runPackageManagerInstall}from"#setup/primitives/pm/run.js";const defaultDeps={detectPackageManager,runPackageManagerInstall};async function installScaffoldDependencies(e){if(!e.changed||e.skip)return;let r=e.deps??defaultDeps,i=await r.detectPackageManager(e.projectPath);await withPhase(e.log,`Installing channel dependencies (${i.kind} install)...`,()=>r.runPackageManagerInstall(i.kind,e.projectPath,{onOutput:createPromptCommandOutput(e.log),signal:e.signal}))||e.log.warning(`Dependency installation failed. The new channel stays unloadable until \`${i.kind} install\` or a deploy succeeds.`)}function reportOverwrittenFiles(e,t){for(let n of t??[])e.warning(`Overwrote ${n}`)}export{installScaffoldDependencies,reportOverwrittenFiles};